import type { DashboardDb } from '../db';

/**
 * The illustrative tables of the owner's template (data/mock.json, generated by scripts/dashboard/import-template.mjs). They are read as text and parsed once, so the
 * type checker does not have to infer the type of a file of this size, and they travel in the chunk of the screen, not in the start-up bundle.
 */
export async function loadTemplateDb(): Promise<DashboardDb> {
  const raw = (await import('../data/mock.json?raw')).default;
  return JSON.parse(raw) as DashboardDb;
}
